import { Argument, Command } from "effect/cli"

class LayoutCommandError extends Schema.TaggedErrorClass<LayoutCommandError>()(
  "LayoutCommandError",
  { message: Schema.String }
) {}

const layouts = [
  { name: "compact", columns: 2, spacing: 8 },
  { name: "comfortable", columns: 3, spacing: 16 },
  { name: "wide", columns: 4, spacing: 24 }
]

