import { Console, Effect } from "effect"
import { Argument, CliError, Command } from "effect/cli"

const layouts = [
  { name: "compact", columns: 2, spacing: 8 },
  { name: "comfortable", columns: 3, spacing: 16 },
  { name: "wide", columns: 4, spacing: 24 }
]

export const previewLayout = Command.make(
  "preview-layout",
  { name: Argument.string("name") },
  ({ name }) =>
    Effect.gen(function*() {
      const layout = layouts.find((candidate) => candidate.name === name)

      if (layout === undefined) {
        return yield* CliError.UserError.make({
          cause: `Unknown layout '${name}'. Choose compact, comfortable, or wide.`
        })
      }

      yield* Console.log(`Layout: ${layout.name}`)
      yield* Console.log(`Columns: ${layout.columns}`)
      yield* Console.log(`Spacing: ${layout.spacing}px`)
    })
)
